// Stub background (installed as background/main.js by test/e2e/20-w2g-room.e2e.mjs) for exercising the real
// content/w2g-room.js: answers the room-side protocol from canned data (./stub-data.js, generated by the test from
// test/fixtures) and records every message. Tests drive it through `self.stub` with serviceWorker.evaluate().
//
// Like the real background, settings live in chrome.storage.local under 'settings' (so the room tab sees changes
// through chrome.storage.onChanged) and sc:expand reads skipPreviews when the request arrives.
import { DATA } from './stub-data.js';

const clone = (x) => JSON.parse(JSON.stringify(x));
const DEFAULT_SETTINGS = { skipPreviews: true, confirmAbove: 100 };

const stub = {
  log: [],
  loggedIn: true,
  // While true, DATA.errors entries with code AUTH_EXPIRED apply (e.g. Daily Drops); a "fresh login" clears it.
  loginExpired: true,
  expandDelayMs: 300,
  libraryDelayMs: 200,

  messages(type) {
    return this.log.filter((e) => e.msg && e.msg.type === type);
  },

  clear() {
    this.log.length = 0;
  },

  /** The latest room:hello per tab: [{ tabId, streamkey, joined, roomName, unreachable, url }]. */
  rooms() {
    const byTab = new Map();
    for (const e of this.messages('room:hello')) byTab.set(e.tabId, Object.assign({ tabId: e.tabId }, e.msg));
    return [...byTab.values()];
  },

  /** Sends a message to frame 0 of a room tab like the real background does; resolves with the response. */
  async sendToRoom(tabId, msg) {
    try {
      const response = await chrome.tabs.sendMessage(tabId, msg, { frameId: 0 });
      return { response: response === undefined ? null : response };
    } catch (e) {
      return { sendError: String((e && e.message) || e) };
    }
  },

  /** Injects the room content scripts again, like the real background does on install/startup. */
  async inject(tabId) {
    const files = chrome.runtime.getManifest().content_scripts[0].js;
    await chrome.scripting.executeScript({ target: { tabId }, files });
    return files;
  },

  async getSettings() {
    const { settings } = await chrome.storage.local.get('settings');
    return Object.assign({}, DEFAULT_SETTINGS, settings);
  },

  /** Writes the settings like background/settings.js does (also what the popup's settings:set ends in). */
  async setSettings(patch) {
    const next = Object.assign(await this.getSettings(), patch);
    await chrome.storage.local.set({ settings: next });
    return next;
  },

  expand(rawUrl, { skipPreviews }) {
    const url = String(rawUrl).split(/[?#]/)[0]; // like the real resolver: ?si=, ?in= etc. don't matter
    const error = DATA.errors[url];
    if (error && (error.code !== 'AUTH_EXPIRED' || this.loginExpired)) return { ok: false, error: clone(error) };
    const entry = DATA.expand[url];
    if (!entry) return { ok: false, error: { code: 'NOT_FOUND', message: 'stub: no canned result for ' + url } };
    const result = clone(entry.result);
    // Mimic the real filter: Go+ previews are skipped only while the setting is on.
    if (!skipPreviews && entry.previews) {
      result.items = result.items.concat(clone(entry.previews));
      result.skipped = result.skipped.filter((s) => s.reason !== 'preview_only');
    }
    return { ok: true, result };
  },

  library() {
    return this.loggedIn
      ? { ok: true, library: clone(DATA.library) }
      : { ok: true, library: { loggedIn: false, sections: [] } };
  },
};
self.stub = stub;

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  stub.log.push({ at: Date.now(), msg, tabId: sender.tab ? sender.tab.id : null, frameId: sender.frameId, url: sender.url });
  switch (msg && msg.type) {
    case 'room:hello':
    case 'room:bye':
    case 'room:active':
    case 'job:progress':
    case 'open:soundcloud':
      sendResponse({ ok: true });
      return false;
    case 'settings:get':
      stub.getSettings().then((settings) => sendResponse({ ok: true, settings }));
      return true;
    case 'settings:set':
      stub.setSettings(msg.patch || {}).then((settings) => sendResponse({ ok: true, settings }));
      return true;
    case 'sc:expand':
      // The setting in effect when the request arrives (background/app.js scExpand), not when the answer leaves.
      stub.getSettings().then((settings) => {
        const response = stub.expand(msg.url, settings);
        setTimeout(() => sendResponse(response), stub.expandDelayMs);
      });
      return true;
    case 'sc:library':
      setTimeout(() => sendResponse(stub.library()), stub.libraryDelayMs);
      return true;
    default:
      return false;
  }
});
